package install

import (
	"path/filepath"
	"strings"
)

func launcherScript(guardBin string) string {
	bin := strings.ReplaceAll(filepath.ToSlash(guardBin), `'`, `'\''`)
	return `#!/bin/sh
# SolonGate hook launcher, generated by ` +
		"`" +
		`solongate init --global` +
		"`" +
		` / ` +
		"`" +
		`repair` +
		"`" +
		`.
#
# Execs the guard binary pinned at install time. Do not edit: a reinstall
# overwrites this file, and on macOS it is chflags-locked besides.

set -u

kind="${1:-}"
[ -n "$kind" ] || { echo "solongate: launcher called with no hook kind" >&2; exit 1; }
shift

home=${HOME:-~}
beatdir="$home/.solongate/.beat"

# The beat. Written BEFORE the binary is checked, because its whole job is to
# record that the client invoked us, which is true even when everything after
# this line fails. The file's modification time is the timestamp; nothing is
# forked to produce one, and the directory test is a builtin.
#
# The braces matter. A redirect into a missing directory is reported by the
# SHELL, before the command runs, so a ` +
		"`" +
		`2>/dev/null` +
		"`" +
		` on the printf alone does
# not suppress it, it lands on the hook's stderr, and Claude Code shows a
# hook's stderr to the person using it. Redirecting the group catches both.
beat() {
  [ -d "$beatdir" ] || mkdir -p "$beatdir" 2>/dev/null || return 0
  { printf '%s\n' "$1" > "$beatdir/$kind"; } 2>/dev/null || true
}

gobin='` + bin + `'

# --sg-doctor: report what would be used and leave. This is what ` +
		"`" +
		`solongate
# doctor` +
		"`" +
		` runs, so the health check exercises the REAL resolution rather than a
# copy of it that can drift.
if [ "$kind" = "--sg-doctor" ]; then
  [ -x "$gobin" ] && { echo "$gobin"; exit 0; }
  echo "no guard binary found" >&2
  exit 1
fi

if [ ! -x "$gobin" ]; then
  beat "no-binary"
  # Nothing can be enforced without the binary, and which way to fail is not a
  # judgement call: the guard is fail-closed, so it refuses the call and says
  # why. Everything else here only records what already happened, and refusing
  # a tool call because the log could not be written would be a worse product
  # than a gap in the log.
  echo "solongate: no guard binary found, so $kind did not run." >&2
  echo "solongate: run \` +
		"`" +
		`solongate repair\` +
		"`" +
		` in a terminal." >&2
  case "$kind" in
    guard) echo "solongate: this tool call is REFUSED, the guard is fail-closed." >&2; exit 2 ;;
    *) exit 0 ;;
  esac
fi

beat "ok"
if [ "$kind" = "guard" ]; then
  exec "$gobin" "$@"
else
  exec "$gobin" "$kind" "$@"
fi
`
}